      if (!name) return;
      const amount = Number(ci.amount);
      const amt = isFinite(amount) ? amount : 0;
      // ÙØ¹Ø§Ù„ Ø¨ÙˆØ¯Ù†: ØµØ±ÛŒØ­ false/0 = Ø®Ø§Ù…ÙˆØ´Ø› Ø¯Ø± ØºÛŒØ± Ø§ÛŒÙ† ØµÙˆØ±Øª Ø§Ú¯Ø± Ù…Ø¨Ù„Øº > 0 ÛŒØ§ enabled true
      let en = true;
