function daysInJMonth(y,m){if(m>=1&&m<=6)return 31;if(m>=7&&m<=11)return 30;return 29;}
function addJDays(startStr,nDays){
  var m=String(startStr||'').trim().match(/(\\d{4})[\\/\\-](\\d{1,2})[\\/\\-](\\d{1,2})/);
  if(!m) return '';
  var y=+m[1], mo=+m[2], d=+m[3];
  // nDays is total inclusive count; advance nDays-1
  var left=(nDays||1)-1;
  while(left>0){
    var dim=daysInJMonth(y,mo);
    var room=dim-d;
    if(left<=room){d+=left;left=0;}
    else{left-=room+1;d=1;mo++;if(mo>12){mo=1;y++;}}
  }
  return y+'/'+String(mo).padStart(2,'0')+'/'+String(d).padStart(2,'0');
}
function jalaliDaysInMonth(y,m){
  y=Number(y)||1405; m=Number(m)||1;
  if(m<=6) return 31;
  if(m<=11) return 30;
  var cy2=y-1309; var mod=((cy2%33)+33)%33;
  var breaks=[1,5,9,13,17,22,26,30];
  return breaks.indexOf(mod)>=0?30:29;
}
function pad2(n){ n=Number(n)||0; return (n<10?'0':'')+n; }
function fillRqDateSelects(){
  var y=0, m=0, grace=0, realY=0, realM=0;
  var realD=0, inGrace=false;
  try{ if(window.__pspRequestYm){ y=Number(window.__pspRequestYm.y)||0; m=Number(window.__pspRequestYm.m)||0; grace=Number(window.__pspRequestYm.grace); if(!isFinite(grace)||grace<0) grace=0; inGrace=!!window.__pspRequestYm.inGrace; realD=Number(window.__pspRequestYm.realD)||0; } }catch(e){}
  try{ if(window.__pspYm){ realY=Number(window.__pspYm.realY||window.__pspYm.y)||0; realM=Number(window.__pspYm.realM||window.__pspYm.m)||0; if(!realD) realD=Number(window.__pspYm.realD)||0; } }catch(e2){}
  if(!y||!m){ y=realY||1405; m=realM||1; }
  if(!realY) realY=y; if(!realM) realM=m;
  // ÙÙ‚Ø· ÙˆÙ‚ØªÛŒ Ø±ÙˆØ² Ø¬Ø§Ø±ÛŒ â‰¤ Ù…Ù‡Ù„Øª: Ù…Ø§Ù‡ Ù‚Ø¨Ù„ Ù…Ø¬Ø§Ø² Ø§Ø³Øª
  if(!inGrace && grace>0 && realD>0 && realD<=grace) inGrace=true;
  if(!inGrace && grace>0 && !realD){
    // Ø¨Ø¯ÙˆÙ† Ø±ÙˆØ² ÙˆØ§Ù‚Ø¹ÛŒ Ø§Ø² Ø³Ø±ÙˆØ±ØŒ ÙÙ‚Ø· Ø¨Ù‡ requestMonth Ø§Ø¹ØªÙ…Ø§Ø¯ Ú©Ù† (Ø§Ú¯Ø± Ø¨Ø§ real ÙØ±Ù‚ Ø¯Ø§Ø±Ø¯ ÛŒØ¹Ù†ÛŒ Ø¯Ø± Ù…Ù‡Ù„Øª)
    if(y && m && realY && realM && (y!==realY || m!==realM)) inGrace=true;
  }
  var start=document.getElementById('rqStart');
  var end=document.getElementById('rqEnd');
  if(!start||!end) return;
  var months=[];
  function pushUnique(yy,mm){
    for(var i=0;i<months.length;i++){ if(months[i].y===yy && months[i].m===mm) return; }
    months.push({y:yy,m:mm});
  }
  if(inGrace){
    var py=realY, pm=realM-1;
    if(pm<1){ pm=12; py=realY-1; }
    pushUnique(py, pm);
    pushUnique(realY, realM);
  } else {
    // Ø®Ø§Ø±Ø¬ Ø§Ø² Ù…Ù‡Ù„Øª: ÙÙ‚Ø· Ù…Ø§Ù‡ Ø¬Ø§Ø±ÛŒ ÙˆØ§Ù‚Ø¹ÛŒ
    pushUnique(realY||y, realM||m);
  }
  function fill(sel){
    var prev=sel.value||'';
    sel.innerHTML='';
    months.forEach(function(mm){
      var dim=jalaliDaysInMonth(mm.y,mm.m);
      for(var d=1; d<=dim; d++){
        var v=mm.y+'/'+pad2(mm.m)+'/'+pad2(d);
        var opt=document.createElement('option');
        opt.value=v; opt.textContent=v;
        sel.appendChild(opt);
      }
    });
    if(prev){ for(var i=0;i<sel.options.length;i++){ if(sel.options[i].value===prev){ sel.selectedIndex=i; return; } } }
    if(sel.options.length) sel.selectedIndex=0;
  }
  fill(start); fill(end);
  start.style.fontFamily='Consolas,Tahoma,monospace';
  end.style.fontFamily='Consolas,Tahoma,monospace';
  start.dir='ltr'; end.dir='ltr';
}
