      +'.jd-sheet *{box-sizing:border-box;}'
      +'.jd-head{text-align:center;font-weight:800;color:#0f766e;padding:8px 10px;background:#ecfdf5;border-bottom:1px solid #99f6e4;font-size:0.9rem;}'
